// School iPad booking - CONFIG (my bookings). Fill in the PUT ... HERE values.
const cfg = {
  SPREADSHEET_ID: 'PUT YOUR GOOGLE SHEET ID HERE',
  BOOKINGS_TAB: 'Bookings',
  TIMEZONE: 'Asia/Kolkata', // school time zone (IANA name)
};
return $input.all().map((i) => ({ json: Object.assign({}, i.json, { _cfg: cfg }) }));

// MY BOOKINGS. The teacher's upcoming bookings (not cancelled, not ended yet), soonest first.
const cfg = $('config').first().json._cfg;
const req = $('config').first().json;
const bookings = $('Sheets - Bookings').all().map((i) => i.json || {});

const now = $now.setZone(cfg.TIMEZONE);
const today = now.toFormat('yyyy-MM-dd');
const nowMin = now.hour * 60 + now.minute;
const pad = (n) => String(n).padStart(2, '0');
const digits = (v) => String(v == null ? '' : v).replace(/\D/g, '');
// 'HH:MM', ISO strings and Sheets time fractions -> minutes since midnight
function toMin(v) {
  if (v == null || v === '') return null;
  const s = String(v).trim();
  if (/^0?\.\d+$/.test(s)) return Math.round(Number(s) * 1440);
  const m = s.match(/(?:T|^)(\d{1,2})[:.](\d{2})/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}
const hhmm = (v) => {
  const m = toMin(v);
  return m == null ? String(v || '') : pad(Math.floor(m / 60)) + ':' + pad(m % 60);
};
function toYMD(v) {
  if (v == null || v === '') return null;
  const s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return DateTime.fromISO(s.slice(0, 10)).isValid ? s.slice(0, 10) : null;
  if (/^\d{5}(\.\d+)?$/.test(s)) return DateTime.fromISO('1899-12-30').plus({ days: Math.floor(Number(s)) }).toFormat('yyyy-MM-dd');
  return null;
}
const notOver = (b) => {
  const d = toYMD(b.date);
  if (!d || d < today) return false;
  if (d > today) return true;
  const end = toMin(b.end_time);
  return end == null || end > nowMin;
};

const phone = digits(req.phone);
const mine = bookings
  .filter((b) => phone && digits(b.phone) === phone
    && String(b.status || '').trim().toLowerCase() === 'booked'
    && notOver(b))
  .map((b) => ({
    booking_id: String(b.booking_id || '').trim(),
    date: toYMD(b.date),
    start_time: hhmm(b.start_time),
    end_time: hhmm(b.end_time),
    devices: b.devices,
    device_ids: b.device_ids,
  }))
  .sort((a, b) => (a.date + a.start_time).localeCompare(b.date + b.start_time));

const lines = mine.map((b) => `${b.booking_id}: ${DateTime.fromISO(b.date).toFormat('ccc d LLL')} ${b.start_time}-${b.end_time}, ${b.devices} iPad(s)`);
const reply = mine.length === 0
  ? 'You have no upcoming iPad bookings.'
  : `Your upcoming booking${mine.length === 1 ? '' : 's'}:\n${lines.join('\n')}`;
return [{ json: { count: mine.length, bookings: mine, lines, reply } }];
